<template><div class="page"><el-card><template #header><div style="display:flex;justify-content:space-between"><span>秒杀活动</span><el-button type="primary" size="small" @click="showDialog=true">新增活动</el-button></div></template><el-table :data="list" border><el-table-column prop="id" label="ID" width="70"/><el-table-column prop="name" label="活动名称"/><el-table-column prop="start_time" label="开始时间" width="170"/><el-table-column prop="end_time" label="结束时间" width="170"/><el-table-column prop="status" label="状态" width="100"><template #default="{row}"><el-tag :type="row.status===1?'success':'info'">{{row.status===1?'进行中':'已结束'}}</el-tag></template></el-table-column><el-table-column label="操作" width="150"><template #default="{row}"><el-button size="small" @click="edit(row)">编辑</el-button><el-button size="small" type="danger" @click="remove(row)">删除</el-button></template></el-table-column></el-table></el-card><el-dialog v-model="showDialog" :title="form.id?'编辑活动':'新增活动'" width="500px"><el-form :model="form" label-width="80px"><el-form-item label="名称"><el-input v-model="form.name"/></el-form-item><el-form-item label="开始时间"><el-date-picker v-model="form.start_time" type="datetime" value-format="YYYY-MM-DD HH:mm:ss" style="width:100%"/></el-form-item><el-form-item label="结束时间"><el-date-picker v-model="form.end_time" type="datetime" value-format="YYYY-MM-DD HH:mm:ss" style="width:100%"/></el-form-item><el-form-item label="状态"><el-switch v-model="form.status" :active-value="1" :inactive-value="0"/></el-form-item></el-form><template #footer><el-button @click="showDialog=false">取消</el-button><el-button type="primary" @click="submit">确定</el-button></template></el-dialog></div></template><script setup>import{ref,reactive,onMounted}from'vue';import{ElMessage,ElMessageBox}from'element-plus';import request from'@/utils/request';const list=ref([]);const showDialog=ref(false);const form=reactive({id:null,name:'',start_time:'',end_time:'',status:1});const loadList=async()=>{const res=await request({url:'/marketing/seckill'});list.value=res.data?.list||res.data||[]};const edit=(row)=>{Object.assign(form,row);showDialog.value=true};const submit=async()=>{if(form.id){await request({url:`/marketing/seckill/${form.id}`,method:'put',data:form})}else{await request({url:'/marketing/seckill',method:'post',data:form})}ElMessage.success('保存成功');showDialog.value=false;loadList()};const remove=async(row)=>{await ElMessageBox.confirm('确定删除？','提示',{type:'warning'});await request({url:`/marketing/seckill/${row.id}`,method:'delete'});ElMessage.success('删除成功');loadList()};onMounted(()=>loadList())</script>
